const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = {};
try { args = JSON.parse(toolCall.function?.arguments || '{}'); } catch(e) { args = {}; }
return [{ json: { toolCallId, doctorName: args.doctorName || '', specialization: args.specialization || '' } }];

const toolCallId = $('Argümanları Çıkar').first().json.toolCallId;
const doctorName = $('Argümanları Çıkar').first().json.doctorName;
const specialization = $('Argümanları Çıkar').first().json.specialization;
const doctors = $input.all().map(i => i.json).filter(r => r.full_name);

if (doctors.length === 0) {
  const searchTerm = doctorName || specialization || 'aradığınız kritere';
  return [{ json: { toolCallId, result: `Üzgünüm, ${searchTerm} uygun doktor bulunamadı. Başka bir uzmanlık alanı veya doktor adı ile tekrar deneyebilirsiniz.` } }];
}

if (doctors.length === 1) {
  const d = doctors[0];
  return [{ json: { toolCallId, result: `${d.full_name}, ${d.specialization} uzmanıdır. Çalışma saatleri: ${d.working_hours || '09:00-18:00'}. Randevu almak ister misiniz?` } }];
}

const list = doctors.map(d => `${d.full_name} (${d.specialization})`).join(', ');
return [{ json: { toolCallId, result: `Kliniğimizde şu doktorlar mevcut: ${list}. Hangi doktorla randevu almak istersiniz?` } }];
